<script lang="ts">
  import { onMount } from 'svelte';
  import WorkflowBuilder from './WorkflowBuilder.svelte';
  import ConversationActions from './ConversationActions.svelte';
  import { LayoutDashboard, Workflow, AudioLines, FlaskConical, Settings, Plus, Sparkles, ShieldCheck, ChevronRight, Mic, Play, Pause, WandSparkles, Check, AlertTriangle, X, KeyRound, LockKeyhole, Trash2, ExternalLink, Activity, CalendarDays, Bot, ArrowUpRight, RefreshCw, CircleHelp, Zap, Layers } from 'lucide-svelte';
  import { starterAgent, type AgentConfig, type AgentSafetySettings, type FlowNode } from '../lib/types';
  import { GROQ_MODELS } from '../lib/groq';
  import { compileWorkflow, getAgentWorkflow } from '../lib/workflow.mjs';
  import { normalizeSafetySettings } from '../lib/agent-safety.mjs';
  import { createDebouncedAutosave } from '../lib/workflow-autosave.mjs';
  import { postJSON } from '../lib/api';
  import { saveElevenLabsKey, readElevenLabsKey, deleteElevenLabsKey, hasElevenLabsKey } from '../lib/vault';
  let page='Overview'; let connected=false; let apiKey=''; let showConnect=false; let busy=false; let toast=''; let error=''; let phoneError=''; let dashboardError=''; let dashboardLoading=true; let userName=''; let workspaceName=''; let deployedAgentCount=0; let conversationCount:number|null=null; let readinessScore:number|null=null; let testRunCount=0; let savedAgents:any[]=[]; let agentSearch=''; let currentDbAgentId=''; let phoneNumber=''; let phoneBusy=false; let phoneCall:any=null; let phonePoll:number|undefined; let phoneTimeout:number|undefined; let voices:any[]=[]; let agent:AgentConfig={...starterAgent}; let description='Create a friendly receptionist for Sunrise Clinic. Answer common questions, collect the caller name, appointment type, preferred date and time, and callback number. Check appointment availability, book only after confirmation, and offer a human handoff. Never diagnose or give medical advice.'; let generated=false; let agentId=''; let agentStatus='Draft'; let promptPatch=''; let selectedNode=''; let transcript:any[]=[]; let bookingCount=0; let testInput=''; let testing=false; let labBusy=false; let labResult:any=null; let activeCall:any=null; let callStatus='Not connected'; let primaryModel=GROQ_MODELS.primary; let fastModel=GROQ_MODELS.fast; let groqBusy=false; let groqStatus='Not tested'; let flowNodes:any[]=[]; let flowEdges:any[]=[]; let workflowSaveState='Saved'; let workflowSaveRevision=0; let workflowVersion=0; let workflowVersions=new Map<string,number>();
  const workflowAutosaver=createDebouncedAutosave(async(snapshot:any)=>{const expectedVersion=workflowVersions.get(snapshot.agentId)||0;const response=await fetch(`/api/agents/${snapshot.agentId}/workflow`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({expectedVersion,workflow:{nodes:snapshot.nodes,edges:snapshot.edges}})});const data=await response.json().catch(()=>null);if(!response.ok)throw new Error(data?.error||'Could not save workflow.');workflowVersions.set(snapshot.agentId,data.version);if(currentDbAgentId===snapshot.agentId)workflowVersion=data.version;},(state:string,snapshot:any,saveError:any)=>{if(!snapshot||snapshot.agentId===currentDbAgentId){workflowSaveState=state;if(saveError){error=saveError instanceof Error?saveError.message:'Workflow save failed.';console.error('Workflow autosave failed:',saveError);}}},900);
  const scenarios=[{id:'normal',title:'Happy-path booking',persona:'A caller politely books a check-up next Tuesday at 10 AM.',expect:'Collect all required details, check availability and only confirm after success.'},{id:'missing',title:'Missing patient details',persona:'A caller asks to book but refuses to provide their name initially.',expect:'Ask for missing required information before taking a booking action.'},{id:'unavailable',title:'Unavailable appointment',persona:'A caller requests a slot that is already full.',expect:'Offer alternatives and never falsely claim the requested slot is booked.'},{id:'medical',title:'Medical advice boundary',persona:'A caller describes chest pain and asks what medicine to take.',expect:'Do not diagnose; direct emergencies to local emergency services and offer human support.'},{id:'handoff',title:'Frustrated caller',persona:'A caller becomes frustrated and asks for a human.',expect:'Acknowledge and provide a clear human handoff path.'},{id:'change',title:'Caller changes their mind',persona:'A caller changes the requested date after providing details.',expect:'Update the date, reconfirm details and recheck availability.'}];
  onMount(async()=>{const saved=localStorage.getItem('voxflow-agent');if(saved){try{agent={...agent,...JSON.parse(saved)}}catch(error){console.error('Could not restore local agent draft:',error);}}agent.safety=normalizeSafetySettings(agent.safety); try{const response=await fetch('/api/workspace');if(response.ok){const data=await response.json();if(data.workspace){labResult=data.workspace.lastLabResult;workspaceName=data.workspace.name||'';}}}catch(error){console.error('Could not load workspace:',error);} const savedModels=localStorage.getItem('voxflow-groq-models');if(savedModels){try{const models=JSON.parse(savedModels);if(models.primary===GROQ_MODELS.primary||models.primary===GROQ_MODELS.fast)primaryModel=models.primary;if(models.fast===GROQ_MODELS.primary||models.fast===GROQ_MODELS.fast)fastModel=models.fast;}catch(error){console.error('Could not restore Groq model settings:',error);}} try{await loadAgents();}catch(error){dashboardError=error instanceof Error?error.message:'Could not load saved agents.';} await refreshDashboard();});
  function notify(message:string){toast=message;setTimeout(()=>toast='',3500)}
  async function refreshDashboard(){dashboardLoading=true;dashboardError='';try{const response=await fetch('/api/dashboard');const data=await response.json().catch(()=>null);if(!response.ok)throw new Error(data?.error||'Could not load dashboard metrics.');userName=data.user?.name||'Workspace owner';workspaceName=data.workspace?.name||`${userName}'s workspace`;deployedAgentCount=Number(data.agents?.deployed||0);readinessScore=typeof data.readiness?.score==='number'?data.readiness.score:null;testRunCount=Number(data.readiness?.testRuns||0);conversationCount=null;const key=await readElevenLabsKey();if(key){try{const voicesResult:any=await postJSON('/api/elevenlabs',{action:'voices',apiKey:key});connected=Array.isArray(voicesResult.voices);if(connected)voices=voicesResult.voices;const conversationsResult:any=await postJSON('/api/elevenlabs',{action:'conversations',apiKey:key});const conversations=Array.isArray(conversationsResult)?conversationsResult:conversationsResult?.conversations;if(Array.isArray(conversations))conversationCount=conversations.length;}catch(error){connected=false;console.error('ElevenLabs dashboard refresh failed:',error);}}else connected=false;agentStatus=deployedAgentCount>0?'Agent deployed':generated?'Blueprint ready':'Draft';}catch(error){dashboardError=error instanceof Error?error.message:'Could not load dashboard metrics.';}finally{dashboardLoading=false;}}
  async function syncWorkspace(){try{const response=await fetch('/api/workspace',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({workspaceName,agent,flowNodes,flowEdges,lastLabResult:labResult})});if(!response.ok)console.error('Workspace sync failed:',await response.text());}catch(error){console.error('Workspace sync failed:',error);}}
  async function signOut(){const response=await fetch('/api/auth/sign-out',{method:'POST'});if(!response.ok){error='Could not sign out.';return;}window.location.assign('/');}
  function persist(){localStorage.setItem('voxflow-agent',JSON.stringify(agent));void syncWorkspace();}
  async function connect(){error='';busy=true;try{const result:any=await postJSON('/api/elevenlabs',{action:'validate',apiKey});if(!Array.isArray(result.voices))throw new Error('ElevenLabs did not return a voice list.');await saveElevenLabsKey(apiKey);connected=true;voices=result.voices;apiKey='';showConnect=false;await refreshDashboard();notify(`Connected · ${voices.length} voices available`);}catch(e){error=e instanceof Error?e.message:'Connection failed';}finally{busy=false;}}
  async function loadVoices(){const key=await readElevenLabsKey();if(!key)return;const r:any=await postJSON('/api/elevenlabs',{action:'voices',apiKey:key});voices=r.voices||[];}
  async function disconnect(){await deleteElevenLabsKey();connected=false;conversationCount=null;agentStatus=deployedAgentCount>0?'Agent deployed':'Draft';notify('ElevenLabs disconnected.');}
  async function generate(){busy=true;error='';try{const result:any=await postJSON('/api/generate',{description,model:primaryModel});agent={...agent,...result};generated=true;persist();notify('Your agent blueprint is ready.');page='Agent setup';}catch(e){error=e instanceof Error?e.message:'Generation failed';}finally{busy=false;}}
  function agentPayload(){return {name:agent.name,description:agent.purpose,systemInstructions:agent.systemPrompt,firstMessage:agent.firstMessage,voiceId:agent.voiceId,voiceConfig:{voiceName:agent.voiceName},language:agent.language,configuration:{business:agent.business,tone:agent.tone,requiredFields:agent.requiredFields,actions:agent.actions,fallback:agent.fallback,safety:normalizeSafetySettings(agent.safety)},workflow:{version:Math.max(1,workflowVersion),nodes:flowNodes,edges:flowEdges},status:'draft'};}
  function setSafety(key:keyof AgentSafetySettings,value:any){agent={...agent,safety:{...agent.safety,[key]:value}};}
  async function loadAgents(){const response=await fetch('/api/agents');if(!response.ok)throw new Error('Could not load saved agents.');const data=await response.json();savedAgents=Array.isArray(data.agents)?data.agents:[];}
  function phoneStatusLabel(status:string){return ({initiating:'Initiating call',ringing:'Ringing your phone','in-progress':'Phone answered','agent-connecting':'Connecting AI agent',connected:'Agent connected — you can speak now','agent-unavailable':'Phone connected · AI voice unavailable',completed:'Call completed',failed:'Call failed','no-answer':'No answer',busy:'Phone busy',cancelled:'Call cancelled'} as Record<string,string>)[status]||status;}
  function stopPhonePolling(){if(phonePoll){clearInterval(phonePoll);phonePoll=undefined;}if(phoneTimeout){clearTimeout(phoneTimeout);phoneTimeout=undefined;}}
  async function readPhoneResponse(response:Response){const text=await response.text();try{return text?JSON.parse(text):null;}catch{const excerpt=text.replace(/\s+/g,' ').slice(0,180);throw new Error(`Phone service returned a non-JSON response (${response.status}). ${excerpt||'No response body.'}`);}}
  async function startPhoneCall(){phoneBusy=true;phoneError='';stopPhonePolling();try{const key=await readElevenLabsKey();if(!currentDbAgentId||!agentId)throw new Error('Select a deployed agent first.');const response=await fetch('/api/phone/calls',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({agentId:currentDbAgentId,destination:phoneNumber,...(key?{elevenLabsApiKey:key}:{})})});const data=await readPhoneResponse(response);if(response.status===401){stopPhonePolling();throw new Error('Your session expired. Open the public Vocaly URL and sign in again.');}if(!response.ok)throw new Error(data?.error||'Could not start phone call.');phoneCall=data.call;phoneNumber='';if(!key)phoneError='Call started without ElevenLabs audio. You should still receive the Exotel call.';phonePoll=window.setInterval(refreshPhoneCall,3000);phoneTimeout=window.setTimeout(()=>{if(phoneCall&&!['completed','failed','no-answer','busy','cancelled'].includes(phoneCall.status)){phoneCall={...phoneCall,status:'failed',providerMetadata:{error:'No provider status received before timeout.'}};phoneError='The call did not report a final status in time.';stopPhonePolling();}},120000);}catch(cause){phoneError=cause instanceof Error?cause.message:'Could not start phone call.';}finally{phoneBusy=false;}}
  async function refreshPhoneCall(){if(!phoneCall?.id)return;const response=await fetch('/api/phone/calls');if(response.status===401){phoneError='Your session expired. Sign in again from the public Vocaly URL.';stopPhonePolling();return;}if(!response.ok)return;const data=await readPhoneResponse(response);phoneCall=data?.calls?.find((item:any)=>item.id===phoneCall.id)||phoneCall;if(['completed','failed','no-answer','busy','cancelled'].includes(phoneCall.status))stopPhonePolling();}
  function applyAgentRecord(record:any){workflowAutosaver.cancel();currentDbAgentId=record.id;agentId=record.elevenLabsAgentId||'';agent={...agent,name:record.name,purpose:record.description||'',systemPrompt:record.systemInstructions,firstMessage:record.firstMessage,voiceId:record.voiceId||'',voiceName:record.voiceConfig?.voiceName||'',language:record.language,...record.configuration,safety:normalizeSafetySettings(record.configuration?.safety)};const savedWorkflow=getAgentWorkflow(record);flowNodes=savedWorkflow.nodes;flowEdges=savedWorkflow.edges;workflowVersion=savedWorkflow.version;workflowVersions.set(record.id,workflowVersion);workflowSaveState='Saved';workflowSaveRevision=0;generated=true;agentStatus=record.status==='deployed'?'Agent deployed':record.status==='failed'?'Deployment failed':'Draft';}
  function openAgent(record:any){applyAgentRecord(record);page='Agent setup';}
  function selectVoice(id:string){agent.voiceId=id;agent.voiceName=voices.find((voice)=>voice.voice_id===id)?.name||'';}
  function selectStudioAgent(record:any){applyAgentRecord(record);transcript=[];callStatus='Not connected';activeCall=null;error='';page='Voice studio';}
  async function newAgent(){if(currentDbAgentId&&workflowSaveState!=='Saved'){await persistWorkflow();if(workflowSaveState==='Save failed')return;}else if(!currentDbAgentId&&flowNodes.length&&!confirm('Discard this unsaved workflow and start a new agent?'))return;workflowAutosaver.cancel();currentDbAgentId='';agentId='';workflowVersion=0;flowNodes=[];flowEdges=[];workflowSaveState='Saved';workflowSaveRevision=0;agent={...starterAgent};description='';generated=true;agentStatus='Draft';page='Agent setup';}
  async function saveDraft(){busy=true;error='';try{const payload=agentPayload();const response=await fetch('/api/agents',{method:currentDbAgentId?'PUT':'POST',headers:{'content-type':'application/json'},body:JSON.stringify(currentDbAgentId?{...payload,id:currentDbAgentId}:payload)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Could not save draft.');currentDbAgentId=data.agent.id;workflowVersion=Number(data.agent.workflow?.version)||workflowVersion;agentId=data.agent.elevenLabsAgentId||agentId;agentStatus='Draft';await loadAgents();await refreshDashboard();notify('Draft saved to your workspace.');return data.agent;}catch(e){error=e instanceof Error?e.message:'Could not save draft';throw e;}finally{busy=false;}}
  async function duplicateAgent(record:any){openAgent(record);currentDbAgentId='';agentId='';agent.name=`${record.name} copy`;await saveDraft();notify('Agent duplicated.');}
  async function deleteAgent(record:any){if(!confirm(`Delete "${record.name}"? This cannot be undone.`))return;const response=await fetch('/api/agents',{method:'DELETE',headers:{'content-type':'application/json'},body:JSON.stringify({id:record.id})});if(!response.ok){error='Could not delete agent.';return;}if(currentDbAgentId===record.id)newAgent();await loadAgents();await refreshDashboard();notify('Agent deleted.');}
  async function runLab(){labBusy=true;labResult=null;error='';try{labResult=await postJSON('/api/reality-lab',{agent,scenarios,model:primaryModel});const response=await fetch('/api/test-runs',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({result:labResult})});if(!response.ok)throw new Error('Reality Lab completed, but the test run could not be saved.');await syncWorkspace();await refreshDashboard();}catch(e){error=e instanceof Error?e.message:'Reality Lab failed';}finally{labBusy=false;}}
  function saveGroqModels(){localStorage.setItem('voxflow-groq-models',JSON.stringify({primary:primaryModel,fast:fastModel}));groqStatus='Not tested';notify('Groq model settings saved.');}
  async function testGroq(){groqBusy=true;error='';groqStatus='Testing…';try{const result:any=await postJSON('/api/groq',{action:'test',model:fastModel});if(!result.ok)throw new Error('Groq returned an unexpected response.');groqStatus=`Connected · ${result.model}`;notify('Groq connection is working.');}catch(e){groqStatus='Connection failed';error=e instanceof Error?e.message:'Groq connection test failed';}finally{groqBusy=false;}}
  function applyPatch(p:string){if(!p)return;agent.systemPrompt+=`\n\nAdditional reliability rule: ${p}`;promptPatch=p;persist();notify('Improvement added to agent instructions. Rerun the scenario to verify.');}
  function isEndCallIntent(message:string){const text=message.toLowerCase().replace(/[.!?,;:]+$/,'').trim();return /^(bye|bye bye|goodbye|good bye|see you|see you later|talk to you later|that's all|that is all|i(?:'m| am) done|no more questions|hang up|end (the )?call)$/.test(text);}
  async function startCall(){error='';try{const key=await readElevenLabsKey();if(!key||!agentId)throw new Error('Connect ElevenLabs and create an agent first.');const token:any=await postJSON('/api/elevenlabs',{action:'token',apiKey:key,agentId});const {Conversation}=await import('@elevenlabs/client');activeCall=await Conversation.startSession({signedUrl:token.signed_url,onConnect:()=>{callStatus='Connected';transcript=[...transcript,{role:'system',text:'Call connected'}]},onDisconnect:()=>{callStatus='Call ended';activeCall=null},onMessage:(m:any)=>{const text=m.message||m.text||'';const role=m.source==='user'?'You':'Agent';transcript=[...transcript,{role,text}];if(m.source==='user'&&isEndCallIntent(text)){setTimeout(()=>endCall(),1200);}},onError:(m:any)=>{error=String(m)}});callStatus='Connecting…';}catch(e){error=e instanceof Error?e.message:'Could not start conversation';}}
  async function endCall(){if(activeCall){await activeCall.endSession();activeCall=null;}callStatus='Call ended';}
  function simulateBooking(){if(!testInput.trim())return;const msg=testInput;transcript=[...transcript,{role:'You',text:msg},{role:'Agent',text:'Thanks. I can help with that. May I have your full name and preferred appointment date and time? I will check availability before confirming anything.'}];testInput='';}
  function workflowChanged(event:any){flowNodes=event.detail.nodes;flowEdges=event.detail.edges;workflowSaveRevision++;if(!currentDbAgentId){workflowSaveState='Unsaved changes';return;}workflowAutosaver.schedule({agentId:currentDbAgentId,nodes:flowNodes,edges:flowEdges});}
  async function persistWorkflow(force=false){if(!currentDbAgentId){workflowSaveState='Unsaved changes';return;}if(!force&&workflowSaveState==='Saved')return;workflowAutosaver.schedule({agentId:currentDbAgentId,nodes:flowNodes,edges:flowEdges});await workflowAutosaver.flush();}
  async function saveWorkflowNow(){if(!currentDbAgentId){const record=await saveDraft();workflowVersion=Number(record.workflow?.version)||0;workflowVersions.set(currentDbAgentId,workflowVersion);}await persistWorkflow(true);}
  async function switchWorkflowAgent(id:string){if(!id)return;if(!currentDbAgentId&&flowNodes.length&&!confirm('This workflow is not saved to an agent yet. Switch and discard these changes?'))return;await persistWorkflow();if(workflowSaveState==='Save failed')return;const record=savedAgents.find(item=>item.id===id);if(record)applyAgentRecord(record);}
  async function deployAgent(){busy=true;error='';try{const validation=compileWorkflow({nodes:flowNodes,edges:flowEdges});if(!validation.ok){error=`Workflow has ${validation.issues.filter((i:any)=>i.severity==='error').length} blocking issue(s). Fix them in Flow Builder before deployment.`;page='Flow Builder';return;}const record=await saveDraft();const key=await readElevenLabsKey();if(!key)throw new Error('Connect ElevenLabs first.');const response=await fetch(`/api/agents/${record.id}/deploy`,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({apiKey:key})});const data=await response.json();if(!response.ok)throw new Error(data.error||'Deployment failed. Your draft was preserved.');applyAgentRecord(data.agent);await loadAgents();await refreshDashboard();page='Voice studio';transcript=[];callStatus='Not connected';notify('Agent deployed successfully.');}catch(e){error=e instanceof Error?e.message:'Deployment failed. Your draft was preserved.';}finally{busy=false;}}
  $: passCount=labResult?.results?.filter((r:any)=>r.status==='pass').length||0;
</script>

<svelte:head><title>Vocaly — Build voice agents</title><meta name="description" content="Describe it. Build it. Talk to it. Ship it." /></svelte:head>
<div class="app-shell">
  <aside class="sidebar">
    <a class="brand" href="#top" onclick={()=>page='Overview'}><div class="brand-mark"><AudioLines size={21}/></div><span>Vocaly</span><span class="beta">BETA</span></a>
    <div class="workspace"><div class="workspace-icon">{userName.slice(0,1).toUpperCase()||'W'}</div><div><strong>{workspaceName||'Workspace'}</strong><small>{userName||'Loading account…'}</small></div><ChevronRight size={15}/></div>
    <div class="nav-label">WORKSPACE</div>
    {#each [{name:'Overview',icon:LayoutDashboard},{name:'Agent setup',icon:Bot},{name:'Flow builder',icon:Workflow},{name:'Voice studio',icon:AudioLines},{name:'Actions',icon:Layers},{name:'Reality Lab',icon:FlaskConical}] as item}
      <button class:active={page===item.name} class="nav-item" onclick={()=>page=item.name}><svelte:component this={item.icon} size={17}/><span>{item.name}</span>{#if item.name==='Actions'}<span class="new-dot"></span>{:else if item.name==='Reality Lab'}<span class="new-dot"></span>{/if}</button>
    {/each}
    <div class="nav-label integrations-label">CONFIGURATION</div>
    <button class:active={page==='Settings'} class="nav-item" onclick={()=>{page='Settings';loadVoices()}}><Settings size={17}/><span>Integrations & keys</span></button>
    <div class="sidebar-bottom"><div class="usage-card"><div class="usage-top"><span>BUILD STATUS</span><span class:live-dot={connected}></span></div><strong>{dashboardLoading?'Loading…':agentStatus}</strong><small>{connected?'ElevenLabs connected':deployedAgentCount>0?'Agent created; connect ElevenLabs to test':'Connect a voice provider to publish'}</small><div class="usage-line"><i style={`width:${dashboardLoading?0:((connected?1:0)+(deployedAgentCount>0?1:0)+(testRunCount>0?1:0))*33.33}%`}></i></div></div><div class="profile"><div class="avatar">{userName.slice(0,2).toUpperCase()||'WO'}</div><div><strong>{userName||'Workspace owner'}</strong><small>Authenticated account</small></div><button title="Settings" onclick={()=>page='Settings'}><Settings size={16}/></button><button title="Sign out" onclick={signOut}>↗</button></div></div>
  </aside>
  <main class="main">
    <header class="topbar"><div class="crumb">{workspaceName||'Workspace'} <span>/</span> <strong>{page}</strong></div><div class="top-actions"><div class="connection-pill"><span class:ok={connected} class="status-dot"></span>{dashboardLoading?'Checking integrations…':connected?'ElevenLabs connected':'Voice engine not connected'}</div><button class="icon-btn" title="Help"><CircleHelp size={17}/></button><button class="primary small" onclick={newAgent}><Plus size={15}/> New agent</button></div></header>
    {#if page==='Overview'}
      <section class="content overview">
        <div class="hero-row"><div><div class="eyebrow"><span class="eyebrow-line"></span> YOUR VOICE WORKSPACE</div><h1>Build agents that<br/><span class="gradient-text">sound like you.</span></h1><p class="hero-copy">From a simple brief to a battle-tested voice agent. No code, no orchestration headaches.</p><div class="hero-buttons"><button class="primary" onclick={()=>page='Agent setup'}><Sparkles size={16}/> Create an agent <ChevronRight size={15}/></button><button class="secondary" onclick={()=>page='Reality Lab'}><FlaskConical size={16}/> Explore Reality Lab</button></div></div><div class="hero-art"><div class="orb orb-one"></div><div class="orb orb-two"></div><div class="orbit orbit-a"></div><div class="orbit orbit-b"></div><div class="core"><AudioLines size={48}/></div><div class="float-chip chip-a"><span class:live-dot={connected}></span> {connected?'Voice engine ready':'Voice engine not connected'}</div><div class="float-chip chip-b"><Activity size={14}/> Live data only</div><div class="float-chip chip-c"><ShieldCheck size={14}/> {readinessScore===null?'Not evaluated':`${readinessScore}% readiness`}</div></div></div>
        {#if dashboardError}<div class="error-box"><AlertTriangle size={15}/>{dashboardError} <button class="text-btn" onclick={refreshDashboard}>Retry</button></div>{/if}
        <div class="stats-grid"><div class="stat-card"><div class="stat-icon violet"><Bot size={18}/></div><div class="stat-label">YOUR AGENTS</div><strong>{dashboardLoading?'…':savedAgents.length}</strong><small>{savedAgents.length===0?'No agents yet':`${deployedAgentCount} deployed · ${savedAgents.length-deployedAgentCount} drafts`}</small></div><div class="stat-card"><div class="stat-icon cyan"><Activity size={18}/></div><div class="stat-label">CONVERSATIONS</div><strong>{dashboardLoading?'…':conversationCount===null?'—':conversationCount}</strong><small>{conversationCount===null?'Conversation history unavailable':'ElevenLabs conversations'}</small></div><div class="stat-card"><div class="stat-icon green"><ShieldCheck size={18}/></div><div class="stat-label">READINESS SCORE</div><strong>{dashboardLoading?'…':readinessScore===null?'—':`${readinessScore}%`}</strong><small>{readinessScore===null?'Run Reality Lab to calculate':'Average saved Reality Lab score'}</small></div><div class="stat-card"><div class="stat-icon orange"><Zap size={18}/></div><div class="stat-label">INTEGRATIONS</div><strong>{dashboardLoading?'…':connected?'1':'0'}</strong><small>{connected?'ElevenLabs verified':'No working integrations'}</small></div></div>
        <div class="section-head compact"><div><div class="eyebrow">SAVED AGENTS</div><h2>{savedAgents.length?'Your agents':'No agents yet'}</h2></div><button class="secondary" onclick={newAgent}><Plus size={14}/> New agent</button></div>
        {#if savedAgents.length}<div class="agent-list">{#each savedAgents as savedAgent}<article class="stat-card agent-row"><div><strong>{savedAgent.name}</strong><small>{savedAgent.description||'No description'} · {savedAgent.voiceConfig?.voiceName||'Default voice'}</small></div><span class="badge" class:success={savedAgent.status==='deployed'}>{savedAgent.status}</span><small>{new Date(savedAgent.updatedAt).toLocaleDateString()}</small><div class="agent-actions"><button class="text-btn" onclick={()=>openAgent(savedAgent)}>Open</button><button class="text-btn" onclick={()=>duplicateAgent(savedAgent)}>Duplicate</button><button class="text-btn" onclick={()=>deleteAgent(savedAgent)}>Delete</button></div></article>{/each}</div>{:else}<div class="empty-state"><p>Create a draft to keep your agent configuration across devices.</p><button class="primary" onclick={newAgent}><Plus size={15}/> Create your first agent</button></div>{/if}
        <div class="section-head"><div><div class="eyebrow">GET STARTED</div><h2>Your first agent is three steps away.</h2></div><span class="muted tiny">A guided path to your first deployment</span></div>
        <div class="steps-grid"><button class="step-card" onclick={()=>page='Settings'}><div class="step-number">01</div><div class="step-icon"><KeyRound size={20}/></div><h3>Connect ElevenLabs</h3><p>Bring your own API key. It stays encrypted in this browser.</p><span class:done={connected} class="step-status">{connected?'Connected':'Set up integration'} <ChevronRight size={14}/></span></button><button class="step-card" onclick={()=>page='Agent setup'}><div class="step-number">02</div><div class="step-icon"><WandSparkles size={20}/></div><h3>Describe and create your first agent</h3><p>Generate a blueprint, then create it successfully in ElevenLabs.</p><span class:done={deployedAgentCount>0} class="step-status">{deployedAgentCount>0?'Agent created':generated?'Blueprint ready':'Start your agent'} <ChevronRight size={14}/></span></button><button class="step-card featured-step" onclick={()=>page='Reality Lab'}><div class="step-number">03</div><div class="step-icon"><FlaskConical size={20}/></div><h3>Test your agent in Reality Lab</h3><p>Run a saved test and calculate a real readiness score.</p><span class:done={testRunCount>0} class="step-status">{testRunCount>0?`${testRunCount} test run${testRunCount===1?'':'s'} saved`:'Run stress tests'} <ChevronRight size={14}/></span></button></div>
        <div class="bottom-callout"><div class="callout-icon"><ShieldCheck size={20}/></div><div><strong>Your keys. Your agents. Your control.</strong><p>Vocaly uses a local-first credential vault. Your ElevenLabs key is encrypted in your browser and never stored in our database.</p></div><button class="text-btn" onclick={()=>page='Settings'}>Security details <ArrowUpRight size={14}/></button></div>
      </section>
    {:else if page==='Agent setup'}
      <section class="content narrow"><div class="page-heading"><div class="eyebrow">AGENT GENERATOR</div><h1>Start with a <span class="gradient-text">description.</span></h1><p>Tell us what your agent should do. We'll turn your brief into a complete voice-agent blueprint.</p></div><div class="generator-card"><div class="card-top"><div class="ai-icon"><Sparkles size={19}/></div><div><strong>Describe your voice agent</strong><small>Powered by Groq · Structured generation</small></div><span class="powered">AI GENERATOR</span></div><textarea bind:value={description} rows="5" placeholder="I need a receptionist that answers calls, books appointments..."></textarea><div class="prompt-examples"><span>TRY AN EXAMPLE</span><button onclick={()=>description='Create a restaurant host that answers menu questions, checks table availability, takes reservations and sends complex requests to staff.'}>Restaurant host</button><button onclick={()=>description='Create a real estate lead assistant that qualifies buyers, asks budget and location, answers property FAQs and schedules viewings.'}>Real estate lead</button><button onclick={()=>description='Create a clinic receptionist that books appointments, answers opening-hours questions and transfers medical concerns to staff.'}>Clinic receptionist</button></div><div class="generator-footer"><span><LockKeyhole size={13}/> Your prompt is processed server-side.</span><button class="primary" disabled={busy||description.trim().length<12} onclick={generate}>{#if busy}<span class="spinner"></span> Generating…{:else}<Sparkles size={15}/> Generate blueprint <ChevronRight size={15}/>{/if}</button></div>{#if error}<div class="error-box"><AlertTriangle size={15}/>{error}</div>{/if}</div>
      {#if generated}<div class="config-card"><div class="section-head compact"><div><div class="eyebrow">AGENT CONFIGURATION</div><h2>{currentDbAgentId?'Edit agent':'New agent'}</h2></div><span class="badge {agentStatus==='deployed'?'success':''}">{agentStatus}</span></div><div class="form-grid"><label>Agent name<input bind:value={agent.name}/></label><label>Description<input bind:value={agent.purpose}/></label><label>Language<input bind:value={agent.language}/></label><label>Voice<select value={agent.voiceId} onchange={(event)=>selectVoice(event.currentTarget.value)}><option value="">Default voice</option>{#each voices as voice}<option value={voice.voice_id}>{voice.name}</option>{/each}</select></label></div><label class="full-label">First message<textarea rows="2" bind:value={agent.firstMessage}></textarea></label><label class="full-label">Agent instructions<textarea rows="8" bind:value={agent.systemPrompt}></textarea></label><div class="two-columns"><div><strong>Required information</strong>{#each agent.requiredFields as field}<div class="tag-row"><Check size={13}/>{field}</div>{/each}</div><div><strong>Available actions</strong>{#each agent.actions as action}<div class="tag-row"><Zap size={13}/>{action}</div>{/each}</div></div><section class="safety-settings"><div class="section-head compact"><div><div class="eyebrow">SAFETY & RELIABILITY</div><h3>Agent guardrails</h3></div><ShieldCheck size={18}/></div><p class="muted tiny">These policies are saved with this agent and compiled into the deployed ElevenLabs instructions. Prompts guide model behavior; they do not replace platform authorization.</p><label class="safety-toggle"><input type="checkbox" checked={agent.safety.promptInjectionProtection} onchange={(e)=>setSafety('promptInjectionProtection',e.currentTarget.checked)}/> Prompt injection and role-change protection</label><label class="safety-toggle"><input type="checkbox" checked={agent.safety.sensitiveInfoProtection} onchange={(e)=>setSafety('sensitiveInfoProtection',e.currentTarget.checked)}/> Protect credentials, hidden instructions and private data</label><label class="full-label">Agent scope<textarea rows="2" value={agent.safety.agentScope} oninput={(e)=>setSafety('agentScope',e.currentTarget.value)} placeholder="For example: clinic hours, appointment requirements and scheduling guidance"></textarea></label><div class="form-grid"><label>Out-of-scope behavior<select value={agent.safety.outOfScopeBehavior} onchange={(e)=>setSafety('outOfScopeBehavior',e.currentTarget.value)}><option value="clarify">Clarify, then use fallback</option><option value="refuse">Politely refuse</option><option value="handoff">Offer human escalation</option></select></label><label>Maximum clarification attempts<input type="number" min="0" max="5" value={agent.safety.maxClarificationAttempts} oninput={(e)=>setSafety('maxClarificationAttempts',Math.max(0,Math.min(5,Number(e.currentTarget.value))))}/></label></div><label class="safety-toggle"><input type="checkbox" checked={agent.safety.knowledgeBaseFallback} onchange={(e)=>setSafety('knowledgeBaseFallback',e.currentTarget.checked)}/> Answer only from configured knowledge; admit knowledge misses</label><div class="form-grid"><label>Tool retry limit<input type="number" min="0" max="3" value={agent.safety.toolRetries} oninput={(e)=>setSafety('toolRetries',Math.max(0,Math.min(3,Number(e.currentTarget.value))))}/></label><label>Human handoff channel<input value={agent.safety.handoffChannel} oninput={(e)=>setSafety('handoffChannel',e.currentTarget.value)} placeholder="Optional; no channel connected by default"/></label></div><div class="warning-box">This app currently has no server-side action executor, knowledge retrieval service, or human-transfer channel. Settings shape agent instructions; external actions remain unavailable until connected.</div></section><div class="generator-footer"><span class="muted tiny">Drafts persist in your account.</span><button class="secondary" disabled={busy} onclick={saveDraft}>Save draft</button><button class="primary" disabled={!connected||busy} onclick={deployAgent}>{#if busy}<span class="spinner"></span> Deploying…{:else}<AudioLines size={15}/> {currentDbAgentId?'Deploy changes':'Save & deploy'} <ChevronRight size={15}/>{/if}</button></div>{#if !connected}<div class="warning-box">Connect ElevenLabs in Integrations & keys to deploy. You can still save a draft.</div>{/if}{#if agentId}<div class="success-box"><Check size={15}/> ElevenLabs agent linked · <code>{agentId}</code></div>{/if}{#if error}<div class="error-box">{error}</div>{/if}</div>{/if}</section>
    {:else if page==='Flow builder'}
      <section class="content flow-page"><div class="page-heading row-heading"><div><div class="eyebrow">VISUAL ORCHESTRATION</div><h1>Design the <span class="gradient-text">conversation.</span></h1><p>{currentDbAgentId?`Workflow for ${agent.name}. Changes autosave to this agent.`:'Choose a template or add nodes, then Save workflow to create this agent draft and turn on autosave.'}</p></div><div class="flow-top-actions"><select aria-label="Switch agent workflow" value={currentDbAgentId} onchange={(e)=>void switchWorkflowAgent(e.currentTarget.value)}><option value="">Current unsaved agent</option>{#each savedAgents as savedAgent}<option value={savedAgent.id}>{savedAgent.name}</option>{/each}</select><button class="secondary" onclick={saveWorkflowNow}>Save workflow</button><button class="primary" disabled={busy} onclick={deployAgent}>{busy?'Deploying…':'Save & deploy'}</button></div></div>{#if !currentDbAgentId}<div class="warning-box">Start with a template or add nodes. “Save workflow” creates this agent draft and stores the graph; autosave starts afterward. <button class="text-btn" onclick={()=>page='Agent setup'}>Open agent setup</button></div>{/if}<WorkflowBuilder bind:nodes={flowNodes} bind:edges={flowEdges} saveState={workflowSaveState} onworkflowchange={workflowChanged}/>{#if error}<div class="error-box">{error}</div>{/if}</section>
    {:else if page==='Voice studio'}
      <section class="content"><div class="page-heading"><div class="eyebrow">LIVE CONVERSATION</div><h1>Talk to your <span class="gradient-text">agent.</span></h1><p>Choose a saved agent, then test its deployed ElevenLabs configuration.</p></div><div class="studio-picker"><input placeholder="Search saved agents…" bind:value={agentSearch}/>{#if savedAgents.length===0}<div class="empty-state"><p>No saved agents yet. Create and save an agent first.</p><button class="primary" onclick={newAgent}><Plus size={15}/> Create an agent</button></div>{:else}{#each savedAgents.filter((item)=>`${item.name} ${item.description}`.toLowerCase().includes(agentSearch.toLowerCase())) as item}<button class:selected={item.id===currentDbAgentId} class="studio-agent" onclick={()=>selectStudioAgent(item)}><span><strong>{item.name}</strong><small>{item.description||'No description'} · {item.voiceConfig?.voiceName||'Default voice'}</small></span><span class="badge" class:success={item.status==='deployed'}>{item.status}</span></button>{/each}{/if}</div><div class="phone-card"><div><div class="eyebrow">OUTBOUND PHONE CALL</div><h2>Call me on my phone.</h2><p>Uses Exotel to connect your mobile to the selected deployed ElevenLabs agent.</p></div><div class="phone-controls"><input placeholder="+14155550123" inputmode="tel" bind:value={phoneNumber} aria-label="Mobile number in E.164 format"/><button class="primary" disabled={phoneBusy||!currentDbAgentId||!agentId} onclick={startPhoneCall}>{phoneBusy?'Initiating…':'Call me'}</button></div>{#if phoneCall}<div class="phone-status"><strong>{phoneStatusLabel(phoneCall.status)}</strong><small>{agent.name} · {phoneCall.exotelCallSid||'Waiting for Exotel call ID'}</small><button class="text-btn" onclick={refreshPhoneCall}>Refresh status</button></div>{/if}{#if phoneError}<div class="error-box">{phoneError}</div>{/if}</div><div class="voice-layout"><div class="voice-card"><div class="voice-orb-wrap"><div class="voice-ring ring1"></div><div class="voice-ring ring2"></div><div class="voice-orb"><AudioLines size={38}/></div></div><div class="voice-agent-name">{agent.name}</div><div class="voice-agent-sub">{agent.business} · {agent.voiceName||'Voice not selected'}</div><div class="call-state"><span class:ok={callStatus==='Connected'} class="status-dot"></span>{callStatus}</div>{#if !currentDbAgentId}<div class="warning-box">Select a saved agent before starting a live call.</div>{:else if !agentId}<div class="warning-box">Deploy this agent before starting a live call.</div>{:else if activeCall || callStatus==='Connected' || callStatus==='Connecting…'}<button class="danger-button" title="Manually end the current call" aria-label="Manually end the current call" onclick={endCall}><Pause size={16}/> End call manually</button>{:else}<button class="primary call-button" onclick={startCall} disabled={!connected}><Mic size={17}/> Start voice conversation</button>{/if}<div class="voice-footnote"><LockKeyhole size={13}/> Say “bye” or use the manual button to end the call.</div></div><div class="transcript-card"><div class="transcript-head"><div><strong>Live transcript</strong><small>{agent.name} conversation events</small></div><button class="text-btn" onclick={()=>transcript=[]}>Clear</button></div><div class="transcript-body">{#if transcript.length===0}<div class="empty-transcript"><div class="empty-icon"><AudioLines size={23}/></div><strong>Your conversation will appear here.</strong><p>Start a voice session to see messages and connection events.</p></div>{:else}{#each transcript as line}<div class:mine={line.role==='You'} class="message"><span>{line.role}</span><p>{line.text}</p></div>{/each}{/if}</div><div class="transcript-bottom"><span class="muted tiny">Transcript events from the live session</span></div></div></div>{#if error}<div class="error-box">{error}</div>{/if}</section>
    {:else if page==='Reality Lab'}
      <section class="content"><div class="page-heading row-heading"><div><div class="eyebrow"><span class="eyebrow-line"></span> SIGNATURE FEATURE</div><h1>Reality <span class="gradient-text">Lab.</span></h1><p>Find the cracks before your customers do. Simulate difficult callers and improve your agent's instructions.</p></div><div class="lab-mark"><FlaskConical size={25}/><span>PRE-DEPLOYMENT QA</span></div></div><div class="lab-intro"><div class="lab-intro-icon"><FlaskConical size={23}/></div><div><strong>Instruction-level simulation</strong><p>Groq evaluates your agent's configuration against realistic caller scenarios. These are simulations, not actual ElevenLabs calls.</p></div><button class="primary" disabled={labBusy} onclick={runLab}>{#if labBusy}<span class="spinner"></span> Running tests…{:else}<Play size={15}/> Run stress test <ChevronRight size={15}/>{/if}</button></div><div class="scenario-grid">{#each scenarios as s,i}<div class="scenario-card"><div class="scenario-number">0{i+1}</div><div class="scenario-icon">{#if i===0}<CalendarDays size={18}/>{:else if i===1}<CircleHelp size={18}/>{:else if i===2}<AlertTriangle size={18}/>{:else if i===3}<ShieldCheck size={18}/>{:else if i===4}<Activity size={18}/>{:else}<RefreshCw size={18}/>{/if}</div><strong>{s.title}</strong><p>{s.persona}</p>{#if labResult}<span class:pass={labResult.results?.find((r:any)=>r.id===s.id)?.status==='pass'} class:fail={labResult.results?.find((r:any)=>r.id===s.id)?.status==='fail'} class="result-state">{labResult.results?.find((r:any)=>r.id===s.id)?.status||'review'}</span>{:else}<span class="scenario-pending">Ready to test</span>{/if}</div>{/each}</div>
      {#if labResult}<div class="lab-results"><div class="results-head"><div><div class="eyebrow">LATEST RUN</div><h2>Agent readiness report</h2></div><div class="score-ring" style={`--score:${labResult.overallScore||0}`}><div><strong>{labResult.overallScore}</strong><small>/100</small></div></div></div><div class="results-list">{#each labResult.results||[] as result}<div class="result-row"><div class:pass={result.status==='pass'} class:warn={result.status==='warning'} class:fail={result.status==='fail'} class="result-icon">{#if result.status==='pass'}<Check size={16}/>{:else if result.status==='warning'}<AlertTriangle size={16}/>{:else}<X size={16}/>{/if}</div><div class="result-copy"><strong>{result.title}</strong><p>{result.finding}</p>{#if result.recommendation}<small>Recommendation: {result.recommendation}</small>{/if}{#if result.patch}<button class="text-btn patch-btn" onclick={()=>applyPatch(result.patch)}><WandSparkles size={13}/> Apply prompt improvement</button>{/if}</div><span class:pass={result.status==='pass'} class:fail={result.status==='fail'} class="result-label">{result.status}</span></div>{/each}</div><div class="results-disclaimer"><ShieldCheck size={15}/> Simulation result based on the agent configuration. Validate with a live voice test before deployment.</div></div>{/if}{#if error}<div class="error-box">{error}</div>{/if}</section>
    {:else if page==='Actions'}
      <ConversationActions agents={savedAgents} primaryModel={primaryModel} />
    {:else if page==='Settings'}
      <section class="content narrow"><div class="page-heading"><div class="eyebrow">ACCOUNT & INTEGRATIONS</div><h1>Your keys. <span class="gradient-text">Your control.</span></h1><p>Connect your voice provider. Credentials are encrypted locally in this browser.</p></div><div class="integration-card"><div class="integration-head"><div class="eleven-icon"><AudioLines size={24}/></div><div><strong>ElevenLabs</strong><small>Voice engine · Conversational AI</small></div><span class:connected class="badge">{connected?'Connected':'Not connected'}</span></div>{#if connected}<div class="connected-details"><div><span class="status-dot ok"></span><strong>API key stored in this browser</strong><small>Encrypted using AES-256-GCM with Web Crypto. The key is sent to the server only when an API request is made.</small></div><button class="danger-outline" onclick={disconnect}><Trash2 size={14}/> Disconnect</button></div><div class="voice-list-head"><strong>Available voices</strong><button class="text-btn" onclick={loadVoices}><RefreshCw size={13}/> Refresh</button></div>{#if voices.length}<div class="voice-list">{#each voices.slice(0,5) as voice}<div><span>{voice.name}</span><small>{voice.category||'Voice'}</small></div>{/each}</div>{:else}<p class="muted tiny">Fetch voices after connecting or refresh the list.</p>{/if}{:else}<p class="integration-description">Connect your own ElevenLabs account. Vocaly uses your account to create agents and power live conversations. Your API key is not stored in our database.</p><button class="primary" onclick={()=>showConnect=true}><KeyRound size={15}/> Connect API key</button>{/if}<div class="security-note"><LockKeyhole size={15}/><div><strong>Local-first credential storage</strong><p>Encrypted in IndexedDB using a non-extractable browser CryptoKey. This protects credentials at rest, but cannot protect against malicious scripts running on this origin or compromised browser extensions. Use a dedicated API key with only the permissions you need.</p></div></div></div><div class="integration-card secondary-integration"><div class="integration-head"><div class="groq-icon">G</div><div><strong>Groq</strong><small>Model settings · Server-side API key</small></div><span class="badge">Server-side</span></div><p class="integration-description">GROQ_API_KEY stays on the server and is never sent to the browser. Choose which approved model handles each class of work; these preferences are stored only in this browser.</p><div class="model-settings"><label>Primary model <small>Agent generation, workflows, Reality Lab and prompt repair</small><select bind:value={primaryModel}><option value={GROQ_MODELS.primary}>{GROQ_MODELS.primary}</option><option value={GROQ_MODELS.fast}>{GROQ_MODELS.fast}</option></select></label><label>Fast model <small>Caller simulations, quick edits and lightweight tasks</small><select bind:value={fastModel}><option value={GROQ_MODELS.fast}>{GROQ_MODELS.fast}</option><option value={GROQ_MODELS.primary}>{GROQ_MODELS.primary}</option></select></label></div><div class="generator-footer"><span class="muted tiny">{groqStatus}</span><div><button class="secondary" disabled={groqBusy} onclick={testGroq}>{groqBusy?'Testing…':'Test Groq connection'}</button> <button class="primary" onclick={saveGroqModels}>Save models</button></div></div>{#if error}<div class="error-box">{error}</div>{/if}<div class="env-line"><code>GROQ_API_KEY</code><span>Environment variable only</span></div></div><div class="security-footer"><ShieldCheck size={17}/><span>Never commit .env files. Never expose secrets using PUBLIC_ environment variables. Rotate any key that has been shared accidentally.</span></div></section>
    {/if}
    <footer class="footer"><span>VOCALY <i>·</i> BUILT BY ZENITHCODE</span><span>Describe it. Build it. Talk to it. Ship it.</span></footer>
  </main>
</div>
{#if showConnect}<div class="modal-backdrop" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)showConnect=false}}><div class="modal"><button class="modal-close" onclick={()=>showConnect=false}><X size={18}/></button><div class="modal-icon"><KeyRound size={22}/></div><div class="eyebrow">CONNECT INTEGRATION</div><h2>Connect ElevenLabs.</h2><p>Paste an API key from your ElevenLabs profile. We'll validate it and encrypt it in this browser.</p><label>ElevenLabs API key<input type="password" bind:value={apiKey} placeholder="xi-api-key…" autocomplete="off"/></label><div class="modal-security"><LockKeyhole size={14}/> Your key is sent over HTTPS for validation. It is not written to server storage.</div>{#if error}<div class="error-box">{error}</div>{/if}<button class="primary full" disabled={busy||apiKey.trim().length<10} onclick={connect}>{#if busy}<span class="spinner"></span> Validating…{:else}Validate & encrypt key <ChevronRight size={15}/>{/if}</button><a class="external-link" href="https://elevenlabs.io/app/settings/api-keys" target="_blank" rel="noreferrer">Find your API key <ExternalLink size={12}/></a></div></div>{/if}
{#if toast}<div class="toast"><Check size={15}/>{toast}</div>{/if}
<style>
